<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';$error=null;if(is_post()){csrf_check();try{$title=trim($_POST['title']??'');$author=trim($_POST['author']??$u['name']);$nim=trim($_POST['nim']??$u['nim']);$program=trim($_POST['study_program']??$u['study_program']);$year=(int)($_POST['publication_year']??0);$advisor=trim($_POST['advisor']??'');$abstract=trim($_POST['abstract']??'');$keywords=trim($_POST['keywords']??'');if(!$title||!$author||!$nim||!$program)throw new RuntimeException('Judul, nama, NIM, dan program studi wajib diisi.');$cover=save_upload($_FILES['cover']??[], 'uploads/repository', ['jpg','jpeg','png','webp'],5242880);$pdf=save_upload($_FILES['pdf']??[], 'uploads/repository', ['pdf'],20971520);$st=$pdo->prepare("INSERT INTO repositories(user_id,title,author,nim,study_program,publication_year,advisor,type,abstract,keywords,file_path,cover,status) VALUES(?,?,?,?,?,?,?,'skripsi',?,?,?,?, 'menunggu')");$st->execute([$u['id'],$title,$author,$nim,$program,$year?:null,$advisor,$abstract,$keywords,$pdf,$cover]);$id=(int)$pdo->lastInsertId();submission_history($pdo,$u['id'],'skripsi',$id,'diajukan','Pengajuan skripsi dibuat');notify_user($pdo,$u['id'],'Skripsi menunggu verifikasi','Pengajuan skripsi “'.$title.'” sedang menunggu verifikasi.');flash('success','Skripsi berhasil diajukan dan menunggu verifikasi.');redirect('/pengguna/riwayat/index.php');}catch(Throwable $e){$error=$e->getMessage();}}render_start('Tambah Skripsi','Pengajuan skripsi baru',$u);dashboard_nav('pengguna');render_mid('Tambah Skripsi','Status awal: Menunggu Verifikasi',$u);if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><?=csrf_input()?><div class="form-grid"><div class="form-group"><label>Judul</label><input class="input" name="title" required></div><div class="form-group"><label>Nama Mahasiswa</label><input class="input" name="author" value="<?=e($u['name'])?>" required></div><div class="form-group"><label>NIM</label><input class="input" name="nim" value="<?=e($u['nim'])?>" required></div><div class="form-group"><label>Program Studi</label><input class="input" name="study_program" value="<?=e($u['study_program'])?>" required></div><div class="form-group"><label>Tahun</label><input class="input" type="number" name="publication_year" min="2000" max="2100"></div><div class="form-group"><label>Dosen Pembimbing</label><input class="input" name="advisor"></div></div><div class="form-group" style="margin-top:14px"><label>Abstrak</label><textarea name="abstract" rows="8"></textarea></div><div class="form-group" style="margin-top:14px"><label>Kata Kunci</label><input class="input" name="keywords"></div><div class="form-grid" style="margin-top:14px"><div class="form-group"><label>Cover (JPG/PNG/WebP, max 5 MB)</label><input class="input" type="file" name="cover" accept="image/*"></div><div class="form-group"><label>File PDF (max 20 MB)</label><input class="input" type="file" name="pdf" accept="application/pdf"></div></div><div style="margin-top:18px"><button class="btn btn-primary">Kirim Pengajuan</button><a class="btn btn-light" style="margin-left:6px" href="/pengguna/tambah/index.php">Batal</a></div></form><?php render_end(); ?>
